import { describe, expect, it } from "vitest";
import { evaluatePolicy } from "./policy-evaluation.js";
const hex64 = (s: string): string => (s + "0".repeat(64)).slice(0, 64);
const base = (facts: unknown[]): unknown => ({
  action: "plan.approve", actor: "principal-1", callerRiskHint: null,
  decisionDigest: hex64("d1"), evaluatedAtEpochMs: 1_760_000_000_000,
  evaluatorVersion: "evaluator-1", facts, graphNodeRevisionRefs: [],
  policyRevisionRef: hex64("a11007"), requiredFactIds: [], scope: [],
  sliceChain: [{ autoApprovalOptIns: [{ action: "plan.approve", tier: "R0" }],
                 rules: [], sliceRef: hex64("a11007") }],
  waivers: [],
});
const shot = (label: string, facts: unknown[]): string => {
  const r = evaluatePolicy(base(facts));
  return `${label} ok=${r.ok} decision=${r.ok ? r.record.decision : "-"} codes=${
    r.ok ? JSON.stringify(r.record.reasonCodes) : "-"}`;
};
describe("PROBE worker-7ac56b35 task-064b9758", () => {
  it("reports each fact-set shape via a forced assertion diff", () => {
    expect([
      shot("EMPTY_FACTS", []),
      shot("ONE_STRONG_R0", [{ factId: "f", tier: "R0", truthClass: "DAEMON_VERIFIED" }]),
      shot("ONE_WEAK_R0", [{ factId: "f", tier: "R0", truthClass: "OBSERVED" }]),
      shot("ONE_NULLTIER_STRONG", [{ factId: "f", tier: null, truthClass: "DAEMON_VERIFIED" }]),
    ]).toEqual(["PROBE_RESULTS_BELOW"]);
  });
});
```
